import { readFileSync } from "node:fs"
import { fileURLToPath } from "node:url"
import { describe, expect, it } from "vitest"
import {
  chainsFor,
  depositAddress,
  forwarderBuild,
  hasForwarderBuild,
  NoForwarderBuild,
} from "../src/forwarder.js"

/** Generated by the sibling repo's WriteAddressVectors.s.sol from the build itself. */
const vectors = JSON.parse(
  readFileSync(
    fileURLToPath(
      new URL(
        "../vendor/cctp-forwarders/forwarders/evm/fixtures/address-vectors.json",
        import.meta.url
      )
    ),
    "utf8"
  )
) as {
  instance: string
  vectors: Array<{ recipient: string; address: string }>
}

describe("the mainnet build", () => {
  it("pins the instance the Solidity fixture was generated from", () => {
    expect(forwarderBuild("mainnet").instance).toBe(vectors.instance)
  })

  it("derives every Solidity-generated vector", () => {
    for (const { recipient, address } of vectors.vectors)
      expect(depositAddress("mainnet", recipient)).toBe(address)
  })

  it("gives the same address for a recipient written in any case", () => {
    const { recipient, address } = vectors
      .vectors[4] as (typeof vectors.vectors)[number]
    expect(
      depositAddress("mainnet", recipient.toUpperCase().replace("0X", "0x"))
    ).toBe(address)
  })

  it("accepts USDC on both chains, at the same address", () => {
    expect([...chainsFor("mainnet")].sort()).toEqual(["avalanche", "polygon"])
  })

  it("refuses a recipient Circle would reject", () => {
    expect(() => depositAddress("mainnet", "0x" + "0".repeat(64))).toThrow(
      "recipient must be non-zero"
    )
  })

  it.each([
    ["too short", "0xdeadbeef"],
    ["an EVM address", "0x3333333333333333333333333333333333333333"],
    ["not hex", "0x" + "g".repeat(64)],
    ["unprefixed", "1".repeat(64)],
  ])("refuses a recipient that is %s", (_label, recipient) => {
    expect(() => depositAddress("mainnet", recipient)).toThrow()
  })
})

describe("the testnet build", () => {
  it("is absent rather than guessed", () => {
    expect(hasForwarderBuild("testnet")).toBe(false)
    expect(() => forwarderBuild("testnet")).toThrow(NoForwarderBuild)
  })

  it("explains what a testnet build would take", () => {
    expect(() =>
      depositAddress("testnet", vectors.vectors[0]?.recipient as string)
    ).toThrow(/changes the creation code and so every deposit address/)
  })
})
